-- 035_d98_honey_types.sql
-- D-98: honey types added from the data-entry forms ("Other"), the beekeeper's honey types and merging two honey types.
--   * HoneyTypes.HoneyTypeTitle: varchar(50) -> nvarchar(100), so a name typed by an officer keeps its Turkish (or Polish,
--     Latvian, Spanish) letters. The unique key on the title is dropped and created again around the widening (its old name
--     was generated by SQL Server, so it is looked up); the values stay the same.
--   * HoneyTypes: CreatedAt, CreatedByUserId, CreatedByOrgId (who added the type from a form; NULL for the types loaded before).
--   * BeekeeperHoneyTypes: the honey types a beekeeper produces (several), recorded at registration.
--   * HoneyTypeMerges: a honey type merged into another by the platform administrator. The source row is removed; its id and
--     title stay here, so deliveries confirmed with the source's id still verify and the old name still points to the target.
--   * TR_RawHoneyProductions_DeliveryLocked (024): the honey type of a lot recorded with containers may change only from a
--     merged source to its target, inside the merge (session key top4.honey_type_merge and a HoneyTypeMerges row). Every other
--     rule of the trigger stays as in 024.
-- Additive and idempotent; a second run changes nothing. SQL Server 2019 (level 150). Run with sqlcmd -I.

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF OBJECT_ID(N'dbo.HoneyTypes', N'U') IS NULL OR OBJECT_ID(N'dbo.Beekeepers', N'U') IS NULL OR OBJECT_ID(N'dbo.Organizations', N'U') IS NULL
BEGIN
    RAISERROR(N'Run 023 first; aborting.', 16, 1);
    SET NOEXEC ON;
END;
GO

-- ---------------------------------------------------------------- HoneyTypeTitle: varchar(50) -> nvarchar(100)

IF EXISTS (SELECT 1 FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
           WHERE c.object_id = OBJECT_ID(N'dbo.HoneyTypes') AND c.name = N'HoneyTypeTitle' AND t.name = N'varchar')
BEGIN
    BEGIN TRANSACTION;
    DECLARE @uq sysname, @sql nvarchar(400);
    -- every unique key on the title alone (one, named UQ__HoneyTyp__... by SQL Server)
    WHILE 1 = 1
    BEGIN
        SET @uq = (SELECT TOP 1 kc.name FROM sys.key_constraints kc
                   JOIN sys.index_columns ic ON ic.object_id = kc.parent_object_id AND ic.index_id = kc.unique_index_id
                   JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
                   WHERE kc.parent_object_id = OBJECT_ID(N'dbo.HoneyTypes') AND kc.type = 'UQ' AND c.name = N'HoneyTypeTitle'
                     AND (SELECT COUNT(*) FROM sys.index_columns x WHERE x.object_id = kc.parent_object_id AND x.index_id = kc.unique_index_id) = 1);
        IF @uq IS NULL BREAK;
        SET @sql = N'ALTER TABLE dbo.HoneyTypes DROP CONSTRAINT ' + QUOTENAME(@uq);
        EXEC sp_executesql @sql;
    END;
    ALTER TABLE dbo.HoneyTypes ALTER COLUMN HoneyTypeTitle nvarchar(100) NOT NULL;
    COMMIT TRANSACTION;
END;
GO
IF NOT EXISTS (SELECT 1 FROM sys.key_constraints WHERE name = N'UQ_HoneyTypes_HoneyTypeTitle' AND parent_object_id = OBJECT_ID(N'dbo.HoneyTypes'))
    ALTER TABLE dbo.HoneyTypes ADD CONSTRAINT UQ_HoneyTypes_HoneyTypeTitle UNIQUE (HoneyTypeTitle);
GO

-- ---------------------------------------------------------------- who added a honey type

IF COL_LENGTH(N'dbo.HoneyTypes', N'CreatedAt') IS NULL
    ALTER TABLE dbo.HoneyTypes ADD
        CreatedAt       datetime2     NULL,
        CreatedByUserId nvarchar(450) NULL,
        CreatedByOrgId  int           NULL CONSTRAINT FK_HoneyTypes_Organizations REFERENCES dbo.Organizations (OrgId);
GO

-- ---------------------------------------------------------------- the beekeeper's honey types

IF OBJECT_ID(N'dbo.BeekeeperHoneyTypes', N'U') IS NULL
CREATE TABLE dbo.BeekeeperHoneyTypes
(
    BeekeeperId nvarchar(450) NOT NULL CONSTRAINT FK_BeekeeperHoneyTypes_Beekeepers REFERENCES dbo.Beekeepers (BeekeeperId),
    HoneyTypeId int           NOT NULL CONSTRAINT FK_BeekeeperHoneyTypes_HoneyTypes REFERENCES dbo.HoneyTypes (HoneyTypeId),
    CONSTRAINT PK_BeekeeperHoneyTypes PRIMARY KEY NONCLUSTERED (BeekeeperId, HoneyTypeId)   -- nonclustered: the key can exceed 900 bytes
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_BeekeeperHoneyTypes_HoneyTypeId' AND object_id = OBJECT_ID(N'dbo.BeekeeperHoneyTypes'))
    CREATE INDEX IX_BeekeeperHoneyTypes_HoneyTypeId ON dbo.BeekeeperHoneyTypes (HoneyTypeId);
GO

-- ---------------------------------------------------------------- merges (the source row is gone; no FK on its id)

IF OBJECT_ID(N'dbo.HoneyTypeMerges', N'U') IS NULL
CREATE TABLE dbo.HoneyTypeMerges
(
    MergeId           int IDENTITY(1, 1) NOT NULL CONSTRAINT PK_HoneyTypeMerges PRIMARY KEY,
    SourceHoneyTypeId int           NOT NULL,
    SourceTitle       nvarchar(100) NOT NULL,
    SourceClass       nvarchar(20)  NULL,
    TargetHoneyTypeId int           NOT NULL CONSTRAINT FK_HoneyTypeMerges_HoneyTypes REFERENCES dbo.HoneyTypes (HoneyTypeId),
    MergedAt          datetime2     NOT NULL,
    MergedByUserId    nvarchar(450) NOT NULL
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'UX_HoneyTypeMerges_Source' AND object_id = OBJECT_ID(N'dbo.HoneyTypeMerges'))
    CREATE UNIQUE INDEX UX_HoneyTypeMerges_Source ON dbo.HoneyTypeMerges (SourceHoneyTypeId);
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'IX_HoneyTypeMerges_Target' AND object_id = OBJECT_ID(N'dbo.HoneyTypeMerges'))
    CREATE INDEX IX_HoneyTypeMerges_Target ON dbo.HoneyTypeMerges (TargetHoneyTypeId);
GO

-- ---------------------------------------------------------------- the delivery lock lets a merge through

CREATE OR ALTER TRIGGER dbo.TR_RawHoneyProductions_DeliveryLocked ON dbo.RawHoneyProductions AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted d JOIN dbo.LotIntakes i ON i.RawHoneyProductionId = d.RawHoneyProductionId AND i.ContainersRecorded = 1)
        RETURN;
    IF EXISTS (
        SELECT 1
        FROM deleted d
        JOIN inserted n ON n.RawHoneyProductionId = d.RawHoneyProductionId
        JOIN dbo.LotIntakes i ON i.RawHoneyProductionId = d.RawHoneyProductionId AND i.ContainersRecorded = 1
        WHERE ISNULL(d.RawHoneyProductionApiaryId, -1) <> ISNULL(n.RawHoneyProductionApiaryId, -1)
           -- D-98: a merged honey type moves to its target only inside the merge
           OR (ISNULL(d.RawHoneyProductionHoneyType, -1) <> ISNULL(n.RawHoneyProductionHoneyType, -1)
               AND NOT (SESSION_CONTEXT(N'top4.honey_type_merge') IS NOT NULL
                        AND EXISTS (SELECT 1 FROM dbo.HoneyTypeMerges m
                                    WHERE m.SourceHoneyTypeId = d.RawHoneyProductionHoneyType AND m.TargetHoneyTypeId = n.RawHoneyProductionHoneyType)))
           OR ISNULL(d.RawHoneyProductionPeriodId, -1) <> ISNULL(n.RawHoneyProductionPeriodId, -1)
           OR ISNULL(d.OriginCountry, '') <> ISNULL(n.OriginCountry, '')
           -- amount and date change only through a confirmed delivery correction
           OR (SESSION_CONTEXT(N'top4.delivery_correction') IS NULL
               AND (ISNULL(d.RawHoneyProductionAmount, -1) <> ISNULL(n.RawHoneyProductionAmount, -1)
                    OR ISNULL(d.RawHoneyProductionDate, '19000101') <> ISNULL(n.RawHoneyProductionDate, '19000101'))))
        THROW 50002, N'The delivery facts of a lot recorded with containers cannot be changed (D-81).', 1;
END;
GO

PRINT '035 done';
GO
